cat > /tmp/test_globals.py <<'EOF'
import functools
import inspect

def outer():
    def inner():
        return 1
    return inner

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def test():
    f = outer()
    w = wrapper(f)

    print(f"f globals: {id(f.__globals__)}")
    print(f"w globals: {id(w.__globals__)}")
    print(f"w.__wrapped__ globals: {id(w.__wrapped__.__globals__)}")

    sig = inspect.signature(w)
    print(f"sig is from w: {sig == inspect.signature(f)}")

if __name__ == "__main__":
    test()
EOF
